#include <algorithm>
#include <chrono>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <vector>
int rank_rows(const uint16_t* rows,int n){uint16_t p[9]={};int r=0;for(int i=0;i<n;i++){auto v=rows[i];while(v){int j=__builtin_ctz(v);if(p[j])v^=p[j];else{p[j]=v;r++;break;}}}return r;}
int rank_columns(const uint16_t* rows,int n){uint16_t a[9];std::copy(rows,rows+n,a);int r=0;for(int c=0;c<n;c++){int p=r;while(p<n&&!(a[p]&(1<<c)))p++;if(p==n)continue;std::swap(a[p],a[r]);for(int i=r+1;i<n;i++)if(a[i]&(1<<c))a[i]^=a[r];r++;}return r;}
int main(int argc,char**argv){if(argc<4)return 1;std::ifstream f(argv[1],std::ios::binary);uint32_t d,b;uint64_t target,dual;f.read((char*)&d,4);f.read((char*)&b,4);f.read((char*)&target,8);f.read((char*)&dual,8);if(d>40||b>81||!f)return 2;std::vector<uint32_t> sizes(b);f.read((char*)sizes.data(),4*b);int n=0;for(auto s:sizes){if(s>9||!s)return 3;n+=s;}std::vector<uint16_t> basis(2*d*n);f.read((char*)basis.data(),2*basis.size());if(!f)return 4;bool affine=std::string(argv[3])=="dual";std::vector<uint64_t> generators;uint64_t offset=0;if(affine){int p=__builtin_ctzll(dual);offset=1ull<<p;for(unsigned i=0;i<d;i++)if(int(i)!=p)generators.push_back((1ull<<i)^(((dual>>i)&1)<<p));}else for(unsigned i=0;i<d;i++)generators.push_back(1ull<<i);if(argc==6){unsigned bits=std::stoul(argv[4]);uint64_t shard=std::stoull(argv[5]);if(bits>generators.size()||shard>=(1ull<<bits))return 5;for(unsigned i=0;i<bits;i++)if((shard>>i)&1)offset^=generators[generators.size()-bits+i];generators.resize(generators.size()-bits);}
std::vector<uint16_t> row(n),col(n);auto toggle=[&](uint64_t coord){while(coord){int bit=__builtin_ctzll(coord);coord&=coord-1;for(int j=0;j<n;j++){row[j]^=basis[bit*n+j];col[j]^=basis[(d+bit)*n+j];}}};toggle(offset);std::ofstream out(argv[2]);out<<"coordinates,row_rank,column_rank\n";auto start=std::chrono::steady_clock::now();uint64_t count=0,previous=0,coordinate=offset,states=1ull<<generators.size();for(uint64_t k=0;k<states;k++){uint64_t gray=k^(k>>1);if(k){int bit=__builtin_ctzll(gray^previous);coordinate^=generators[bit];toggle(generators[bit]);}previous=gray;if(!coordinate)continue;int rr=0,rc=0,pos=0;bool rejected=false;for(auto s:sizes){rr+=(affine?rank_columns:rank_rows)(row.data()+pos,s);rc+=(affine?rank_columns:rank_rows)(col.data()+pos,s);pos+=s;if(rr*rc>501){rejected=true;break;}}if(!rejected){count++;out<<coordinate<<","<<rr<<","<<rc<<"\n";}}std::cout<<"dimension "<<d<<" visited "<<states<<" cheap "<<count<<" seconds "<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<"\n";}
